  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main">
      <div id="root"></div>
    </main>

    <script>
      const notificationOptions = [
        { id: "notification-email", value: "email", label: "Email" },
        { id: "notification-sms", value: "sms", label: "SMS" },
        {
          id: "notification-push",
          value: "push-notifications",
          label: "Push Notifications",
        },
      ];

      function RadioOption({ id, value, label, name }) {
        return `
          <label class="radio-card" for="${id}">
            <input id="${id}" type="radio" name="${name}" value="${value}" required>
            <span class="radio-label">${label}</span>
          </label>
        `;
      }

      function NotificationPreferenceForm() {
        const name = "notification-preference";
        const options = notificationOptions
          .map((option) => RadioOption({ ...option, name }))
          .join("");

        return `
          <section class="card" aria-labelledby="form-title">
            <form id="notification-form" novalidate>
              <p class="required-note"><span aria-hidden="true">*</span> Required field</p>
              <div class="form-field">
                <fieldset aria-describedby="notification-help notification-error">
                  <legend>
                    How do you prefer to receive notifications?
                    <span aria-hidden="true">*</span>
                  </legend>
                  <p class="field-help" id="notification-help">Choose one notification method.</p>
                  <div class="radio-options">
                    ${options}
                  </div>
                  <p class="field-error" id="notification-error" hidden>
                    Error: Choose a notification method before saving.
                  </p>
                </fieldset>
              </div>
              <button type="submit">Save notification preference</button>
              <p class="status-message" id="form-status" aria-live="polite"></p>
            </form>
          </section>
        `;
      }

      function App() {
        return `
          <div class="page-shell">
            <header class="hero">
              <p class="eyebrow">Preferences</p>
              <h1 id="form-title">Notification settings</h1>
              <p class="intro">
                Tell us where to send timely updates. You can change this preference later.
              </p>
            </header>
            ${NotificationPreferenceForm()}
          </div>
        `;
      }

      document.querySelector("#root").innerHTML = App();

      document
        .querySelector("#notification-form")
        .addEventListener("submit", (event) => {
          event.preventDefault();

          const form = event.currentTarget;
          const status = document.querySelector("#form-status");
          const error = document.querySelector("#notification-error");
          const radios = form.querySelectorAll('input[name="notification-preference"]');

          if (!form.reportValidity()) {
            error.hidden = false;
            radios.forEach((radio) => radio.setAttribute("aria-invalid", "true"));
            status.textContent = "";
            return;
          }

          const selected = new FormData(form).get("notification-preference");
          const label = notificationOptions.find((option) => option.value === selected).label;
          error.hidden = true;
          radios.forEach((radio) => radio.removeAttribute("aria-invalid"));
          status.textContent = `Preference saved: ${label}.`;
        });

      document
        .querySelectorAll('input[name="notification-preference"]')
        .forEach((radio) => {
          radio.addEventListener("change", () => {
            document.querySelector("#notification-error").hidden = true;
            document
              .querySelectorAll('input[name="notification-preference"]')
              .forEach((item) => item.removeAttribute("aria-invalid"));
          });
        });
    </script>
  </body>
</html>
